def test_setattr_inherited_attribute_on_instance_undo() -> None:
    class A:
        x = 1

    a = A()
    monkeypatch = MonkeyPatch()
    monkeypatch.setattr(a, "x", 2)
    assert a.x == 2
    assert vars(a) == {"x": 2}
    monkeypatch.undo()
    assert a.x == 1
    assert vars(a) == {}
    A.x = 3
    assert a.x == 3


def test_setattr_inherited_descriptor_on_instance_undo() -> None:
    counter = 0

    class A:
        @property
        def value(self) -> int:
            nonlocal counter
            counter += 1
            return counter

        # A non-data descriptor, so setting it on the instance is allowed.
        method = property(lambda self: None).getter  # placeholder, replaced below

    class NonDataDescriptor:
        def __get__(self, obj: object, objtype: type | None = None) -> int:
            nonlocal counter
            counter += 1
            return counter

    A.method = NonDataDescriptor()  # type: ignore[assignment]

    a = A()
    monkeypatch = MonkeyPatch()
    monkeypatch.setattr(a, "method", 42)
    assert a.method == 42
    monkeypatch.undo()
    assert "method" not in vars(a)
    first = a.method
    assert a.method == first + 1


